mean3() {
    awk -F'\t' '
        # Skip the header line (first line of the input)
        NR == 1 { next }

        # For each remaining line, check whether the third field is numeric
        $3 ~ /^[+-]?[0-9]+\.?[0-9]*$/ {
            sum += $3          # Add the numeric value to a running total
            count++            # Increment the count of valid rows
        }

        # After processing all lines, output the mean if at least one valid row was found
        END {
            if (count > 0)
                printf "%.2f\n", sum / count
            else
                print "No numeric values found in column 3"
        }
    '
}
```

